import {fresh,normalize,today,uid,tasks,upsertTask,reset,start,startBreak,tick,buy,ITEMS,minutesOn,petName,upcoming,addAlarm,dueReminders} from './domain.mjs';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='mochi-study.web.v1',BAK=KEY+'.backup';
let state=fresh(),readOnly=true,ready=false,exportOriginal=false,view='tasks',viewedDate=today(),lastDay=today(),editId=null,editDate=today(),toastTimeout,previous=performance.now(),checkpoint=0,deadlineCheckpoint=0,releaseLock,audioContext,eyeRest=null,eyeResume=false,reminderQueue=[];
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').hidden=true,5000);}
function notice(message,action=false){const n=$('storage-notice');n.replaceChildren(document.createTextNode(message));n.hidden=false;if(action){const b=document.createElement('button');b.textContent='重新打开';b.onclick=()=>location.reload();n.append(b);}}
function load(){
 const raw=localStorage.getItem(KEY);if(!raw)return fresh();
 try{return normalize(JSON.parse(raw));}catch(e){
  let parsed;try{parsed=JSON.parse(raw);}catch{}
  if(parsed?.webVersion>1){readOnly=true;exportOriginal=true;notice('存档来自更新的网页版，已停止写入。可先导出备份，再刷新到最新版本。');return fresh();}
  const backup=localStorage.getItem(BAK);if(backup){try{const restored=normalize(JSON.parse(backup));if(!readOnly)localStorage.setItem(KEY+'.recovery.'+Date.now(),raw);notice('主存档读取失败，已恢复上一份备份。请导出一份备份留存。');return restored;}catch{}}
  readOnly=true;exportOriginal=true;notice('存档暂时无法读取，已停止写入以保留原文件。请先导出备份，反馈问题后再恢复。');return fresh();
 }
}
function save(){if(readOnly)return false;try{
 const old=localStorage.getItem(KEY),next=JSON.stringify(state);if(old!==next){if(old){try{normalize(JSON.parse(old));localStorage.setItem(BAK,old);}catch{}}localStorage.setItem(KEY,next);}return true;
 }catch{readOnly=true;state.timer.running=false;notice('浏览器暂时无法保存进度，计时已暂停。请立即在设置中导出备份。');toast('保存失败，当前进度仍可导出。');return false;}}
function mutate(fn,message){if(readOnly){toast('此页面暂时不能修改。请查看页面上方的存档提示。');return false;}try{fn();const saved=save();render();if(saved&&message)toast(message);return saved;}catch(e){toast(e.message||'操作未完成，请重试。');return false;}}
function beep(){if(!state.settings.soundEnabled)return;try{if(audioContext?.state==='running'){const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=660;gain.gain.setValueAtTime(.05,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.4);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+.4);}}catch{}}
function unlockAudio(){try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume().catch(()=>{});}catch{}}
document.addEventListener('pointerdown',unlockAudio,{once:true});document.addEventListener('keydown',unlockAudio,{once:true});
function celebrate(message){$('pet-message').textContent=message;$('pet-stage').classList.remove('celebrate');void $('pet-stage').offsetWidth;$('pet-stage').classList.add('celebrate');setTimeout(()=>$('pet-stage').classList.remove('celebrate'),1600);}
function navigate(next){view=next;for(const b of document.querySelectorAll('[data-view]')){const active=b.dataset.view===view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}for(const s of document.querySelectorAll('.view'))s.hidden=s.id!=='view-'+view;render();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
const quadrants=[['重要且紧急','先处理，让心里轻一点',true,true,'q0'],['重要不紧急','留给成长，也留给自己',true,false,'q1'],['紧急不重要','尽快处理，别占据太多时间',false,true,'q2'],['不重要不紧急','有余力时，再慢慢完成',false,false,'q3']];
function renderTasks(){
 const items=tasks(state,viewedDate),isToday=viewedDate===today(),done=items.filter(x=>x.done).length;
 $('task-summary').textContent=items.length?`已完成 ${done} / ${items.length} 件任务。${done===items.length?'今天的努力，搭子都看见啦。':'一步一步，就会离目标更近。'}`:'还没有任务，从一件小事开始。';
 $('today-label').textContent=new Date(viewedDate+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
 $('history-date').value=viewedDate;$('add-task').disabled=!isToday||readOnly;$('history-hint').textContent=isToday?'':'历史任务仅供查看';
 $('quadrants').innerHTML=quadrants.map(([title,subtitle,important,urgent,key],index)=>{
  const group=items.filter(x=>x.important===important&&x.urgent===urgent);
  return `<article class="quadrant ${key}"><div class="quadrant-heading"><h2>${title}</h2><span class="count">${group.length}</span></div><p class="quadrant-subtitle">${subtitle}</p>${group.length?`<ul class="task-list">${group.map(x=>`<li class="task-row ${x.done?'done':''}"><input type="checkbox" data-toggle="${esc(x.id)}" ${x.done?'checked':''} ${!isToday||readOnly?'disabled':''} aria-label="完成任务：${esc(x.title)}"><span class="task-title">${esc(x.title)}</span>${isToday?`<span class="task-actions"><button data-edit="${esc(x.id)}" ${readOnly?'disabled':''} aria-label="编辑：${esc(x.title)}">编辑</button><button data-delete="${esc(x.id)}" ${readOnly?'disabled':''} aria-label="删除：${esc(x.title)}">删除</button></span>`:''}</li>`).join('')}</ul>`:`<div class="empty-quadrant">${['先做一件要紧的小事','给值得的事留点时间','把琐事轻轻放下','这里可以留一点空白'][index]}</div>`}${isToday?`<button class="quadrant-add" data-add="${index}" ${readOnly?'disabled':''}>＋ 添加一件事</button>`:''}</article>`;
 }).join('');
 for(const input of $('quadrants').querySelectorAll('[data-toggle]')){const item=items.find(x=>x.id===input.dataset.toggle);if(item?.dueAt){const label=document.createElement('small');label.className='task-deadline-chip';label.textContent='DDL · '+formatDate(item.dueAt);input.nextElementSibling.append(label);}}
}
function openTask(id=null,index=1,date=viewedDate){if(readOnly)return toast('请先查看存档提示。');if(date!==today()&&!id)return;editId=id;editDate=date;const item=tasks(state,date).find(x=>x.id===id),q=quadrants[index];$('task-dialog-title').textContent=id?'编辑任务与 DDL':'新增任务';$('task-title').value=item?.title||'';$('task-important').checked=item?item.important:q[2];$('task-urgent').checked=item?item.urgent:q[3];$('task-deadline').value=item?.dueAt?localInput(item.dueAt):'';$('task-reminder').value=String(item?.lead??15);$('task-dialog').showModal();$('task-title').focus();}
$('add-task').onclick=()=>openTask();$('quadrants').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add!==undefined)openTask(null,Number(b.dataset.add));if(b.dataset.edit)openTask(b.dataset.edit);if(b.dataset.delete){const item=tasks(state).find(x=>x.id===b.dataset.delete);if(item&&confirm(`删除“${item.title}”？`))mutate(()=>{state.days[today()]=tasks(state).filter(x=>x.id!==item.id);},'任务已删除。');}});
$('quadrants').addEventListener('change',e=>{const id=e.target.dataset.toggle;if(!id)return;const item=tasks(state).find(x=>x.id===id);if(item&&mutate(()=>{item.done=e.target.checked;}))if(item.done)celebrate('完成一件事，今天又向前一点！');});
$('task-form').onsubmit=e=>{e.preventDefault();const due=$('task-deadline').value;if(due&&!Number.isFinite(Date.parse(due)))return toast('请填写完整的 DDL 日期和时间。');if(mutate(()=>upsertTask(state,editDate,$('task-title').value,$('task-important').checked,$('task-urgent').checked,editId,due?new Date(due).toISOString():'',Number($('task-reminder').value)),'任务保存好了。'))$('task-dialog').close();};
$('history-date').onchange=()=>{if(/^\d{4}-\d{2}-\d{2}$/.test($('history-date').value)){viewedDate=$('history-date').value;renderTasks();}};$('back-today').onclick=()=>{viewedDate=today();renderTasks();};
function countdown(value){const n=Math.ceil(Math.max(0,value));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function phaseText(){return {focus:state.timer.running?'正在专注':'专注时间',focusDone:'专注完成啦',break:state.timer.running?'好好休息一下':'休息已暂停',breakDone:'休息完成啦'}[state.timer.phase];}
function controls(){const t=state.timer,disabled=readOnly?'disabled':'';if(t.phase==='focusDone')return `<button class="primary" data-timer="break" ${disabled}>开始休息</button><button class="quiet" data-timer="next" ${disabled}>下一轮专注</button>`;if(t.phase==='breakDone')return `<button class="primary" data-timer="next" ${disabled}>下一轮专注</button>`;return `<button class="primary" data-timer="${t.running?'pause':'resume'}" ${disabled}>${t.running?'暂停':t.id||t.phase==='break'?'继续':'开始专注'}</button><button class="quiet" data-timer="reset" ${disabled}>${t.phase==='break'?'结束休息':'重置本轮'}</button>`;}
function renderTimer(){const t=state.timer,n=countdown(t.remaining);for(const id of ['main-countdown','side-countdown','mini-countdown'])$(id).textContent=n;for(const id of ['phase-label','side-phase','mini-phase'])$(id).textContent=phaseText();$('timer-progress').style.width=`${Math.max(0,Math.min(100,(1-t.remaining/t.duration)*100))}%`;
 $('side-focus').textContent=t.running?'查看倒计时':t.phase==='focusDone'?'专注完成啦':'一起专注';
 document.title=`${t.running?n+' · ':''}${petName(state)}陪你学习 · 糯米学习`;
}
function renderFocus(){const select=$('focus-task'),old=select.value;select.innerHTML='<option value="">自由专注</option>'+tasks(state).filter(x=>!x.done).map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('');if([...select.options].some(x=>x.value===old))select.value=old;select.disabled=readOnly||!!state.timer.id||state.timer.phase!=='focus';
 const t=state.timer;$('session-note').textContent=t.phase==='focusDone'?`这轮完成了 ${t.minutes} 分钟专注，奖励已记入钱包。`:`${t.id&&t.taskTitle?'本轮：'+t.taskTitle+'。':''}完整完成一轮，可获得 ${t.id?t.minutes:state.settings.focusMinutes} 金币。`;
 $('eye-policy').textContent=state.settings.eyeEnabled?`每 ${state.settings.eyeMinutes} 分钟有效专注提醒一次；提醒可能受浏览器后台限制。`:'用眼提醒已关闭，可以在设置中开启。';
 for(const id of ['focus-controls','mini-controls'])$(id).innerHTML=controls();renderTimer();
}
function timerAction(action){if(readOnly)return toast('请先查看存档提示。');previous=performance.now();if(action==='pause')mutate(()=>{state.timer.running=false;},'先歇一会儿，进度会留着。');
 else if(action==='resume')mutate(()=>{const item=tasks(state).find(x=>x.id===$('focus-task').value);start(state,item?.title||'');});
 else if(action==='break')mutate(()=>startBreak(state));
 else if(action==='next')mutate(()=>{reset(state);start(state);});
 else if(action==='reset'){if(state.timer.id&&state.timer.phase==='focus'&&!confirm('重置会放弃本轮进度，这一轮不会获得金币。继续吗？'))return;mutate(()=>reset(state),'已准备好下一轮。');}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-timer]');if(b)timerAction(b.dataset.timer);});$('side-focus').onclick=()=>navigate('focus');
function renderPet(){const name=petName(state),kind=state.pet.kind;for(const id of ['pet-image','mini-pet']){$(id).src=`assets/${kind}.png`;$(id).alt=`${{cat:'银渐层小猫',bunny:'糯米小兔',dog:'金毛小狗'}[kind]}${name}`;}
 $('pet-name').textContent=name;$('mini-name').textContent=name;const done=tasks(state).filter(x=>x.done).length,focus=state.records.filter(x=>x.date===today()).length;const energy=Math.min(100,70+done*3+focus*2),mood=Math.min(100,65+done*5+focus*3);for(const [key,val] of [['energy',energy],['mood',mood]]){$(key+'-bar').style.width=val+'%';$(key+'-value').textContent=val;}
 for(const slot of ['hat','outfit','accessory']){const item=ITEMS.find(x=>x.id===state.pet[slot]),node=$('pet-'+slot);node.textContent=item?.icon||'';node.className='pet-item '+slot+(item?.id==='accessory-glasses'?' glasses':item?.id==='accessory-satchel'?' satchel':'');}
 $('pet-stage').dataset.kind=kind;
 if($('pet-dialog').open)renderPetChoices();
}
function renderPetChoices(){document.querySelectorAll('[data-pet]').forEach(b=>{const selected=b.dataset.pet===state.pet.kind;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});$('pet-name-input').value=petName(state);}
$('pet-button').onclick=()=>{renderPetChoices();$('pet-dialog').showModal();};document.querySelectorAll('[data-pet]').forEach(b=>b.onclick=()=>mutate(()=>{state.pet.kind=b.dataset.pet;},'新的搭子来陪你啦。'));
$('pet-name-form').onsubmit=e=>{e.preventDefault();const name=$('pet-name-input').value.trim();if(!name)return toast('给搭子起个名字吧。');if(mutate(()=>{state.pet[state.pet.kind+'Name']=name.slice(0,12);},'搭子的名字保存好了。'))$('pet-dialog').close();};
function renderShop(){
 $('shop-grid').innerHTML=ITEMS.map(item=>{const owned=state.owned.includes(item.id),wear=state.pet[item.slot]===item.id;return `<article class="shop-item"><div class="shop-icon" aria-hidden="true">${item.icon}</div><h2>${item.name}</h2><p>${item.description}</p>${owned?'<span class="owned-badge">已在衣柜里</span>':''}<button data-buy="${item.id}" class="${owned?'quiet':'primary'}" ${readOnly||wear?'disabled':''}>${wear?'正在穿戴':owned?'穿上它':`🪙 ${item.price} 金币 · 购买`}</button></article>`;}).join('');
 $('wardrobe-items').innerHTML=['hat','outfit','accessory'].map(slot=>`<div class="wardrobe-row"><span>${{hat:'帽子',outfit:'衣物',accessory:'饰品'}[slot]}</span><button data-unequip="${slot}" class="${state.pet[slot]==='none'?'active':''}" ${readOnly?'disabled':''}>不穿戴</button>${ITEMS.filter(x=>x.slot===slot&&state.owned.includes(x.id)).map(x=>`<button data-buy="${x.id}" class="${state.pet[slot]===x.id?'active':''}" ${readOnly?'disabled':''}>${x.icon} ${x.name}</button>`).join('')}</div>`).join('');
}
document.addEventListener('click',e=>{const buyButton=e.target.closest('[data-buy]'),unwear=e.target.closest('[data-unequip]');if(buyButton){let item;if(mutate(()=>{item=buy(state,buyButton.dataset.buy);},'已经给搭子穿好啦。'))celebrate(`${item.name}，很适合今天的我！`);}if(unwear)mutate(()=>{state.pet[unwear.dataset.unequip]='none';});});
function renderStats(){const total=state.records.reduce((n,x)=>n+x.minutes,0),earned=state.records.reduce((n,x)=>n+x.coins,0),daily=minutesOn(state,today());$('stats-cards').innerHTML=[['今日专注',daily+' 分钟',`目标 ${state.settings.goalMinutes} 分钟`],['累计专注',total+' 分钟',`${state.records.length} 轮完整专注`],['累计赚取',earned+' 金币','每一轮认真，都有回响']].map(([label,value,sub])=>`<div class="stat-card"><p>${label}</p><strong>${value}</strong><small>${sub}</small></div>`).join('');
 const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {date:today(d),label:(d.getMonth()+1)+'/'+d.getDate()};}),max=Math.max(state.settings.goalMinutes,...days.map(x=>minutesOn(state,x.date)));
 $('week-chart').innerHTML=days.map(x=>{const value=minutesOn(state,x.date);return `<div class="chart-column ${x.date===today()?'current':''}" aria-label="${x.date} 专注 ${value} 分钟"><strong>${value} 分</strong><div class="bar" style="height:${Math.max(3,value/max*135)}px"></div><small>${x.date===today()?'今天':x.label}</small></div>`;}).join('');$('goal-note').textContent=`今日完成 ${daily} / ${state.settings.goalMinutes} 分钟。${daily>=state.settings.goalMinutes?'今天的目标已经达成啦！':'给自己一点时间，一点点靠近目标。'}`;
 $('records-list').innerHTML=state.records.length?state.records.slice(-30).reverse().map(x=>`<div class="record-row"><div>${esc(x.taskTitle||'自由专注')}<small>${x.date}</small></div><strong>${x.minutes} 分钟 · ＋${x.coins} 金币</strong></div>`).join(''):'<div class="empty-quadrant">完成第一轮专注，就会留下你的足迹。</div>';
}
function render(){$('coin-count').textContent=state.coins;renderTasks();renderPet();renderFocus();renderShop();renderStats();renderDeadlines();renderAlarms();}
const fields=[['focusMinutes','专注时长（分钟）',5,90],['shortBreakMinutes','短休息（分钟）',1,30],['longBreakMinutes','长休息（分钟）',1,30],['cycles','长休息间隔（轮）',2,8],['eyeMinutes','用眼提醒（分钟）',10,60],['goalMinutes','每日目标（分钟）',30,480]];
$('settings-button').onclick=()=>{$('settings-fields').innerHTML=fields.map(([name,label,min,max])=>`<label>${label}<input type="number" name="${name}" min="${min}" max="${max}" step="1" required value="${state.settings[name]}"></label>`).join('');for(const key of ['eyeEnabled','soundEnabled'])$('settings-form').elements[key].checked=state.settings[key];$('settings-dialog').showModal();};
$('settings-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;const settings={...state.settings};for(const [key,,min,max]of fields){const n=Number(form.elements[key].value);if(!Number.isInteger(n)||n<min||n>max)return toast('请填写范围内的整数。');settings[key]=n;}for(const key of ['eyeEnabled','soundEnabled'])settings[key]=form.elements[key].checked;if(mutate(()=>{state.settings=settings;if(!state.timer.id&&state.timer.phase==='focus')reset(state);},'新的学习节奏保存好了。'))$('settings-dialog').close();};
function download(value,name){const url=URL.createObjectURL(new Blob([value],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export-button').onclick=()=>{try{const original=exportOriginal?localStorage.getItem(KEY):null;download(original||JSON.stringify({...state,timer:{...state.timer,running:false}},null,2),`MochiStudy-Web-${today()}.json`);toast('备份已导出，请妥善保存。');}catch{download(JSON.stringify(state,null,2),`MochiStudy-Web-${today()}.json`);}};
$('import-button').onclick=()=>{if(readOnly)return toast('当前页面不能覆盖存档，请查看顶部提示。');$('import-file').click();};
$('import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2*1024*1024)throw Error('备份文件过大，请选择 2 MB 以内的网页版备份。');const imported=normalize(JSON.parse(await file.text()));if(!confirm('导入将替换当前浏览器的学习进度。建议先导出当前备份。继续吗？'))return;if(mutate(()=>{state=imported;previous=performance.now();},'备份已导入，计时保持暂停。'))$('settings-dialog').close();}catch(err){toast(err.message||'备份无法读取。');}};
for(const button of document.querySelectorAll('[data-close]'))button.onclick=()=>button.closest('dialog').close();
$('compact-button').onclick=()=>{document.body.classList.add('compact');$('mini-clock').hidden=false;renderFocus();};$('expand-button').onclick=()=>{document.body.classList.remove('compact');$('mini-clock').hidden=true;};
function showEye(){beep();if(!$('eye-dialog').open)$('eye-dialog').showModal();$('eye-countdown').textContent='20 秒';$('eye-rest').textContent='开始休息';$('eye-rest').disabled=readOnly;$('eye-later').disabled=readOnly;}
$('eye-later').onclick=()=>{if(readOnly){eyeRest=null;state.timer.running=false;$('eye-dialog').close();return;}mutate(()=>{state.timer.eyeElapsed=Math.max(0,state.settings.eyeMinutes*60-300);});$('eye-dialog').close();};
$('eye-rest').onclick=()=>{if(eyeRest!==null)return;if(mutate(()=>{eyeResume=state.timer.running;state.timer.running=false;})){eyeRest=20;$('eye-rest').disabled=true;$('eye-later').disabled=true;previous=performance.now();}};
$('eye-dialog').addEventListener('cancel',e=>{e.preventDefault();if(eyeRest===null||readOnly)$('eye-later').click();});
setInterval(()=>{if(!ready||readOnly)return;const now=performance.now(),delta=(now-previous)/1000;previous=now;const day=today();if(day!==lastDay){if(viewedDate===lastDay)viewedDate=day;lastDay=day;render();}checkReminders();deadlineCheckpoint+=delta;if(deadlineCheckpoint>=30){deadlineCheckpoint=0;renderDeadlines();}
 if(eyeRest!==null){if(delta>0&&delta<=5)eyeRest=Math.max(0,eyeRest-delta);$('eye-countdown').textContent=Math.ceil(eyeRest)+' 秒';if(eyeRest===0){eyeRest=null;state.timer.eyeElapsed=0;state.timer.running=eyeResume;save();$('eye-dialog').close();$('eye-rest').disabled=false;$('eye-later').disabled=false;toast('眼睛休息好了，我们慢慢继续。');renderFocus();}return;}
 const event=tick(state,delta,day);if(event.gap){notice('浏览器刚才暂停了页面，专注已暂停并保留进度。准备好后点击“继续”。');save();renderFocus();}
 if(event.focusDone){save();if($('eye-dialog').open)$('eye-dialog').close();render();celebrate(`认真完成一轮，收下 ${event.reward} 金币！`);toast(`专注完成！获得 ${event.reward} 金币，记得休息一下。`);beep();}
 else if(event.breakDone){save();render();toast('休息完成啦，准备好后再开始下一轮。');beep();}
 else if(event.eye){save();showEye();}
 else renderTimer();
 checkpoint+=delta;if(checkpoint>=5){checkpoint=0;if(state.timer.running)save();}
},500);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)return;if(ready&&!readOnly)save();});
window.addEventListener('pagehide',()=>{if(ready&&!readOnly){state.timer.running=false;save();}ready=false;readOnly=true;releaseLock?.();});
window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
window.addEventListener('storage',e=>{if(e.key===KEY&&readOnly){try{state=normalize(JSON.parse(e.newValue));render();}catch{}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'){e.preventDefault();navigate('tasks');viewedDate=today();openTask();}});
function boot(writable){readOnly=!writable;try{state=load();}catch{readOnly=true;notice('此浏览器暂时无法访问本地存档。请换用普通窗口，并允许网站保存数据。');}ready=true;previous=performance.now();if(!writable)notice('另一个糯米学习页面正在使用这份进度。本页仅供查看；关闭另一个页面后，可重新打开本页。',true);if(writable&&!readOnly)save();render();}
if(navigator.locks){navigator.locks.request('mochi-study-web-single-writer',{ifAvailable:true},async lock=>{if(!lock){boot(false);return;}boot(true);await new Promise(resolve=>{releaseLock=resolve;});}).catch(()=>{boot(false);notice('浏览器暂时无法锁定存档，已停止修改。请关闭其他页面后重新打开。',true);});}
else{boot(false);notice('此浏览器缺少可靠的存档保护功能。请使用较新的 Edge、Chrome 或 Firefox。');}
function formatDate(at){return new Date(at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false});}
function localInput(at){const d=new Date(at);return `${today(d)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function renderDeadlines(){const list=upcoming(state),soon=list.slice(0,3);$('ddl-summary').textContent=list.length?`${list.length} 件待完成`:'重要的时间，提前记下来';$('ddl-list').innerHTML=soon.length?soon.map(x=>{const ms=Date.parse(x.dueAt)-Date.now(),remaining=ms<0?'已过截止时间':ms<3600000?`还剩 ${Math.max(1,Math.ceil(ms/60000))} 分钟`:ms<86400000?`还剩 ${Math.ceil(ms/3600000)} 小时`:`还剩 ${Math.ceil(ms/86400000)} 天`;return `<div class="ddl-row ${ms<0?'overdue':''}"><input type="checkbox" data-ddl-complete="${esc(x.id)}" data-date="${x.date}" ${readOnly?'disabled':''} aria-label="完成 DDL：${esc(x.title)}"><div><strong>${esc(x.title)}</strong><small>${formatDate(x.dueAt)} 截止 · ${remaining}</small></div><button data-ddl-edit="${esc(x.id)}" data-date="${x.date}" ${readOnly?'disabled':''}>编辑</button></div>`;}).join(''):'<p class="ddl-empty">把作业、考试或会议的截止时间放在这里，搭子会提前提醒你。</p>';}
$('add-ddl').onclick=()=>{viewedDate=today();navigate('tasks');openTask(null,0,today());$('task-dialog-title').textContent='设置 DDL';};
$('ddl-list').addEventListener('click',e=>{const b=e.target.closest('[data-ddl-edit]');if(b)openTask(b.dataset.ddlEdit,0,b.dataset.date);});
$('ddl-list').addEventListener('change',e=>{const b=e.target;if(!b.dataset.ddlComplete)return;const x=tasks(state,b.dataset.date).find(x=>x.id===b.dataset.ddlComplete);if(x&&mutate(()=>{x.done=true;},'这个 DDL 已完成啦。'))celebrate('重要的事情做好了，真安心！');});
function renderAlarms(){const list=[...state.alarms].sort((a,b)=>Date.parse(a.at)-Date.parse(b.at));$('alarm-list').innerHTML=list.length?list.map(x=>`<div class="alarm-row"><input type="checkbox" data-alarm-toggle="${esc(x.id)}" ${x.enabled?'checked':''} ${readOnly?'disabled':''} aria-label="启用闹钟：${esc(x.title)}"><div>${esc(x.title)}<small>${formatDate(x.at)} · ${x.notified?'已提醒':x.enabled?'等待响铃':'已关闭'}</small></div><button data-alarm-delete="${esc(x.id)}" ${readOnly?'disabled':''}>删除</button></div>`).join(''):'<p class="muted">还没有闹钟。给下一件重要的事设个时间吧。</p>';}
$('alarm-button').onclick=()=>{renderAlarms();const d=new Date(Date.now()+3600000);$('alarm-time').value=localInput(d.toISOString());$('alarm-dialog').showModal();notificationStatus();};
$('alarm-form').onsubmit=e=>{e.preventDefault();const at=$('alarm-time').value;if(!at||Date.parse(at)<=Date.now())return toast('请选择未来的闹钟时间。');if(mutate(()=>addAlarm(state,$('alarm-title').value,new Date(at).toISOString()),'闹钟已经设好。')){$('alarm-title').value='';renderAlarms();}};
$('alarm-list').addEventListener('change',e=>{const id=e.target.dataset.alarmToggle;if(!id)return;const x=state.alarms.find(x=>x.id===id);if(!x)return;if(e.target.checked&&Date.parse(x.at)<=Date.now()){toast('这个闹钟时间已过，请添加一个新的时间。');renderAlarms();return;}mutate(()=>{x.enabled=e.target.checked;});});
$('alarm-list').addEventListener('click',e=>{const b=e.target.closest('[data-alarm-delete]');if(b&&confirm('删除这个闹钟？'))mutate(()=>{state.alarms=state.alarms.filter(x=>x.id!==b.dataset.alarmDelete);},'闹钟已删除。');});
function notificationStatus(){const support='Notification'in window,status=support?Notification.permission:'unavailable';$('notification-button').disabled=status==='granted'||status==='unavailable';$('notification-button').textContent=status==='granted'?'系统通知已允许':status==='unavailable'?'此浏览器不支持系统通知':'开启系统通知（可选）';$('notification-status').textContent=status==='denied'?'系统通知已被浏览器禁止，可在网站权限中自行调整。页面内弹窗仍可使用。':status==='granted'?'页面打开时可显示系统通知。关闭网页后不会响铃；后台提醒可能延后。':'允许后，页面打开时也可通过系统通知提醒。关闭网页后不会响铃；后台提醒可能延后。';}
$('notification-button').onclick=async()=>{if(!('Notification'in window))return;try{await Notification.requestPermission();notificationStatus();}catch{toast('系统通知暂时无法开启，页面内提醒仍可使用。');}};
function checkReminders(){const due=dueReminders(state);if(!due.length)return;save();reminderQueue.push(...due);$('reminder-content').innerHTML=reminderQueue.map(x=>`<div class="reminder-row"><p><b>${x.type==='ddl'?'DDL 提醒':'闹钟'} · ${esc(x.title)}</b></p><small>${x.type==='ddl'?'截止时间':'提醒时间'}：${formatDate(x.at)}${Date.parse(x.at)<Date.now()?' · 时间已到':''}</small></div>`).join('');if(!$('reminder-dialog').open)$('reminder-dialog').showModal();beep();renderAlarms();if('Notification'in window&&Notification.permission==='granted')try{new Notification('糯米学习提醒',{body:due.map(x=>`${x.title} · ${formatDate(x.at)}`).join('\n'),icon:new URL(`assets/${state.pet.kind}.png`,location.href).href});}catch{}}
$('reminder-dialog').addEventListener('close',()=>{reminderQueue=[];});
const toolLifecycle=new AbortController();
if(document.modelContext?.registerTool){
 for(const tool of [
 {name:'add_daily_task',title:'添加糯米学习任务',description:'在当前浏览器的今日四象限中新增任务并保存。可选设置 DDL 与提前提醒；不会同步或发送给他人。',inputSchema:{type:'object',properties:{title:{type:'string',minLength:1,maxLength:100},important:{type:'boolean'},urgent:{type:'boolean'},dueAt:{type:'string'},leadMinutes:{type:'integer',minimum:0,maximum:1440}},required:['title','important','urgent'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!ready||readOnly)throw Error('当前页面无法修改存档。');if(!input||typeof input.title!=='string'||!input.title.trim()||input.title.length>100||typeof input.important!=='boolean'||typeof input.urgent!=='boolean')throw Error('任务名称和重要/紧急属性无效。');if(input.dueAt&&(!Number.isFinite(Date.parse(input.dueAt))||typeof input.dueAt!=='string'))throw Error('DDL 时间无效。');if(input.leadMinutes!==undefined&&(!Number.isInteger(input.leadMinutes)||input.leadMinutes<0||input.leadMinutes>1440))throw Error('提前提醒时间无效。');let item;if(!mutate(()=>{item=upsertTask(state,today(),input.title,input.important,input.urgent,null,input.dueAt||'',input.leadMinutes??15);}))throw Error('任务未能保存。');viewedDate=today();navigate('tasks');return {id:item.id,title:item.title,date:today(),saved:true};}},
 {name:'choose_study_companion',title:'选择学习搭子',description:'选择小猫、小兔或金毛小狗，可为该搭子命名，保存在当前浏览器。',inputSchema:{type:'object',properties:{kind:{type:'string',enum:['cat','bunny','dog']},name:{type:'string',minLength:1,maxLength:12}},required:['kind'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!ready||readOnly)throw Error('当前页面无法修改存档。');if(!['cat','bunny','dog'].includes(input?.kind)||input.name!==undefined&&(typeof input.name!=='string'||!input.name.trim()||input.name.length>12))throw Error('搭子种类或名字无效。');if(!mutate(()=>{state.pet.kind=input.kind;if(input.name)state.pet[input.kind+'Name']=input.name.trim();}))throw Error('搭子未能保存。');return {kind:state.pet.kind,name:petName(state),saved:true};}}
 ])try{Promise.resolve(document.modelContext.registerTool(tool,{signal:toolLifecycle.signal})).catch(()=>{});}catch{}
}
window.addEventListener('pagehide',()=>toolLifecycle.abort());
